// Headers can only be inferred from a data row, and an empty tab has none - so on an
// empty tab this cannot tell 'no headers' from 'headers but no data'. Say so rather
// than guessing, and let the write below be the real test.
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const headers = rows.length ? Object.keys(rows[0]) : [];
const now = new Date().toISOString();
let verdict;
if (!rows.length) {
  verdict = 'Tab is empty of data rows, which is expected on a fresh sheet. Headers cannot be '
    + 'checked from here. THE REAL TEST IS NODE 3 BELOW - if it goes green, open the Leads tab '
    + 'and press Ctrl+End to find the row it wrote.';
} else if (!headers.includes('phone')) {
  verdict = 'The phone column is MISSING from row 1. appendOrUpdate matches on it, so the write cannot work.';
} else {
  verdict = 'Headers look right. If the write below still fails, read its red error.';
}
return [{ json: {
  __diagnostic: { data_rows_found: rows.length, headers_seen: headers, header_count: headers.length,
    has_phone_column: headers.includes('phone'), verdict },
  lead_id: 'DIAG' + Date.now(), created_at: now, name: 'DIAGNOSTIC TEST - delete me',
  phone: '0000000000', wa_id: '910000000000', status: 'New', source: 'diagnostic', last_touch: now
} }];
